def fail(msg):
    try:(DATA_DIR/"update_restart_error.txt").write_text(str(msg),encoding="utf-8")
    except Exception:pass
    raise SystemExit(str(msg))

def safe_backup():
    rows=[]
    if BACKUPS.exists():
        for p in BACKUPS.glob("before-"+TARGET_VERSION+"-*"):
            if (p/"server.py").exists() and (p/"index.html").exists():
                try:rows.append((p.stat().st_mtime,p))
                except Exception:pass
    if not rows:fail("V5 OTA could not find the safe pre-update backup. No prospect data was changed.")
    return max(rows,key=lambda x:x[0])[1]

